<div class="customer-form-heading"><div><div class="breadcrumb-line">Home <span>&rsaquo;</span> Suppliers <span>&rsaquo;</span> <b>View Supplier</b></div><h1><?= e($supplier['name']) ?></h1></div><a href="index.php?page=admin&amp;section=suppliers" class="btn btn-light">Back to Suppliers</a></div>
<div class="admin-panel supplier-view-card"><div class="supplier-view-header"><div><span class="modal-eyebrow"><?= e($supplier['supplier_code']) ?></span><h2>Supplier Details</h2></div><a class="btn btn-outline-primary" href="index.php?page=admin&amp;section=suppliers-edit&amp;id=<?= (int) $supplier['id'] ?>">Edit Supplier</a></div><div class="supplier-detail-grid"><div><span>Contact Person</span><strong><?= e($supplier['contact_person'] ?: '-') ?></strong></div><div><span>Phone</span><strong><?= e($supplier['phone']) ?></strong></div><div><span>Email</span><strong><?= e($supplier['email'] ?: '-') ?></strong></div><div><span>Status</span><strong><?= e(ucfirst($supplier['status'])) ?></strong></div><div class="supplier-detail-wide"><span>Address</span><strong><?= nl2br(e($supplier['address'] ?: '-')) ?></strong></div></div><div class="supplier-view-product-list"><h3>Products from this Supplier</h3><?php if (!$products): ?><p class="empty-note">No products added for this supplier.</p><?php else: ?><div class="table-responsive"><table class="table admin-table"><thead><tr><th>Code</th><th>Product</th><th>Category</th><th>Unit</th><th>Buying Price</th><th>Opening Qty</th></tr></thead><tbody><?php foreach ($products as $product): ?><tr><td><?= e($product['product_code'] ?: '-') ?></td><td><?= e($product['product_name']) ?></td><td><?= e($product['category'] ?: '-') ?></td><td><?= e($product['unit']) ?></td><td><?= number_format((float) $product['buying_price'], 2) ?></td><td><?= number_format((float) $product['opening_quantity'], 2) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div>
